<?php
function categoryLifecycle(string $level,int $id): void { ?>
<details class="inline-details lifecycle-menu"><summary title="Restore or safely delete" aria-label="Restore or safely delete"><span aria-hidden="true">⋯</span> More actions</summary><form method="post" action="<?= e(url('/categories')) ?>"><?php categoryHidden('restore',$level,$id); ?><button class="secondary">Restore</button></form><form method="post" action="<?= e(url('/categories')) ?>" data-confirm="Permanently delete this archived entry? This cannot be undone. Linked products, child categories or historical references will block deletion."><?php categoryHidden('delete',$level,$id); ?><button class="danger-button">Delete permanently if safe</button></form></details>
<?php }
function categoryTransfer(array $sub,array $categories): void { foreach (['move_subcategory'=>'Move to main category','merge_subcategory'=>'Merge into subcategory'] as $action=>$label): ?>
<form class="editor transfer-form" method="post" action="<?= e(url('/categories')) ?>" data-confirm="Move or merge this subcategory? Linked products will be reassigned and the original entry retained in the archive."><?php categoryHidden($action,'subcategory',(int)$sub['id']); ?><label><?= e($label) ?><select name="target_id" required><option value="">Choose destination</option><?php foreach ($categories as $parent): if ($parent['archived_at'] || $parent['status']!=='active') continue; ?><?php if ($action==='move_subcategory'): if ((int)$parent['id']===(int)$sub['category_id']) continue; ?><option value="<?= (int)$parent['id'] ?>"><?= e($parent['name']) ?></option><?php else: foreach ($parent['subcategories'] as $target): if ($target['archived_at'] || $target['status']!=='active' || $target['id']===$sub['id']) continue; ?><option value="<?= (int)$target['id'] ?>"><?= e($parent['name'].' / '.$target['name']) ?></option><?php endforeach; endif; endforeach; ?></select></label><button class="secondary"><?= e($label) ?></button></form>
<?php endforeach; }
